<?php
/** Keep configured school logos while upgrading the bundled application emblem. */
function school_logo():string{
    $configured=trim(setting('logo_path'));
    return in_array($configured,['','assets/logo.svg','./assets/logo.svg','/assets/logo.svg'],true)
        ? 'assets/student-grade-logo.png'
        : $configured;
}
function page_start(string $title,string $subtitle=''):void{$GLOBALS['pageTitle']=$title;require __DIR__.'/header.php';echo '<div class="page-heading"><div><p class="eyebrow">ACADEMIC RECORDS & INSIGHTS</p><h1>'.h($title).'</h1>'.($subtitle?'<p class="text-secondary">'.h($subtitle).'</p>':'').'</div></div>';}
function page_end():void{require __DIR__.'/footer.php';}
function field_id(string $name):string{static $seen=[];$seen[$name]=($seen[$name]??0)+1;return $name.($seen[$name]>1?'-'.$seen[$name]:'');}
function input_field(string $name,string $label,mixed $value='',string $type='text',bool $required=true,string $extra=''):void{$id=field_id($name);echo '<div class="field"><label for="'.h($id).'">'.h($label).'</label><input class="form-control" id="'.h($id).'" name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.($required?'required ':'').$extra.'></div>';}
function select_field(string $name,string $label,array $options,mixed $value='',bool $required=true):void{$id=field_id($name);echo '<div class="field"><label for="'.h($id).'">'.h($label).'</label><select class="form-select" id="'.h($id).'" name="'.h($name).'" '.($required?'required':'').'><option value="">Choose…</option>';foreach($options as $k=>$v)echo '<option value="'.h($k).'" '.((string)$value===(string)$k?'selected':'').'>'.h($v).'</option>';echo '</select></div>';}
function choices(string $table,string $label='name',string $where='1=1'):array{$out=[];if($table==='terms'&&$where==='1=1')$data=rows("SELECT t.id,CONCAT(y.name,' · ',t.name) label FROM terms t JOIN school_years y ON y.id=t.school_year_id ORDER BY y.starts_on DESC,t.starts_on");else $data=rows("SELECT id,`$label` AS label FROM `$table` WHERE $where ORDER BY `$label`");foreach($data as $r)$out[$r['id']]=$r['label'];return $out;}
function offerings_choices():array{require_staff();[$scope,$params]=scope_sql();$out=[];foreach(rows("SELECT o.id,CONCAT(s.subject_code,' · ',COALESCE(t.name,o.legacy_term),' · ',COALESCE(se.name,'Review required')) label FROM offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN terms t ON t.id=o.term_id LEFT JOIN sections se ON se.id=o.section_id WHERE $scope ORDER BY o.id DESC",$params)as $r)$out[$r['id']]=$r['label'];return $out;}
function data_table(array $data,array $columns,?callable $actions=null):void{echo '<div class="table-responsive"><table class="table align-middle"><thead><tr>';foreach($columns as $label)echo '<th>'.h($label).'</th>';if($actions)echo '<th class="no-print">Actions</th>';echo '</tr></thead><tbody>';if(!$data)echo '<tr><td colspan="'.(count($columns)+($actions?1:0)).'" class="empty-state">No matching records.</td></tr>';foreach($data as $r){echo '<tr>';foreach($columns as $key=>$label)echo '<td>'.h($r[$key]??'—').'</td>';if($actions){echo '<td class="no-print actions">';$actions($r);echo '</td>';}echo '</tr>';}echo '</tbody></table></div>';}
function pagination(int $total,int $page,int $size=15):void{if($total<=$size)return;$pages=(int)ceil($total/$size);echo '<nav aria-label="Record pages" class="pagination-wrap">';for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++){echo '<a class="btn btn-sm '.($page===$p?'btn-primary':'btn-outline-secondary').'" href="?'.h(http_build_query(array_merge($_GET,['page'=>$p]))).'">'.$p.'</a> ';}echo '<span class="text-secondary"> '.$total.' records · page '.$page.' of '.$pages.'</span></nav>';}
function post_button(string $action,int $id,string $label,string $confirm=''):void{echo '<form method="post" class="d-inline"'.($confirm?' data-confirm="'.h($confirm).'"':'').'>';csrf_field();echo '<input type="hidden" name="id" value="'.$id.'"><button class="btn btn-sm btn-outline-secondary" name="action" value="'.h($action).'">'.h($label).'</button></form>';}
function date_filters(array $source):array{$where=[];$params=[];foreach(['from','to']as $key){$v=trim(request_string($source,$key));if($v!==''){if(!valid_date($v))throw new DomainException('Choose valid filter dates.');$where[]=$key;$params[$key]=$v;}}if(isset($params['from'],$params['to'])&&$params['from']>$params['to'])throw new DomainException('From date must be before the end date.');return $params;}
